ST.xhtml:p:
prog_id := 4;

(* CSP 形态：目标位置直接上总线（%QW0-2）；驱动器（仿真侧）轴速限速跟随并闭位置环 *)
AxisX_cmd := x_tgt;
AxisY_cmd := y_tgt;
AxisZ_cmd := z_tgt;

(* 状态输出 *)
pen_down := AxisZ_pos <= 1;
any_moving := (AxisX_pos > AxisX_cmd + 1) OR (AxisX_pos < AxisX_cmd - 1)
           OR (AxisY_pos > AxisY_cmd + 1) OR (AxisY_pos < AxisY_cmd - 1)
           OR (AxisZ_pos > AxisZ_cmd + 1) OR (AxisZ_pos < AxisZ_cmd - 1);

IF cmd_reset THEN
    state := 0;
    plot_done := FALSE;
    x_tgt := 50; y_tgt := 50; z_tgt := 10;
ELSIF state = 0 THEN
    x_tgt := 50; y_tgt := 50; z_tgt := 10;      (* 待机：抬笔回中心 *)
    IF cmd_draw AND run THEN
        state := 1;
    END_IF;
ELSE
    CASE state OF
        1:                                      (* 抬笔至安全高度 *)
            z_tgt := 10;
            IF AxisZ_pos >= 9 THEN
                state := 2;
            END_IF;
        2:                                      (* 抬笔态定位起点 (20,20) *)
            x_tgt := 20; y_tgt := 20; z_tgt := 10;
            IF (AxisX_pos <= 21) AND (AxisX_pos >= 19) AND (AxisY_pos <= 21) AND (AxisY_pos >= 19) THEN
                state := 3;
            END_IF;
        3:                                      (* 落笔（接触建立，不判位置相等） *)
            z_tgt := 0;
            IF AxisZ_pos <= 1 THEN
                state := 4;
            END_IF;
        4:                                      (* 边 1：(20,20)->(80,20) *)
            x_tgt := 80;
            IF (AxisX_pos <= 81) AND (AxisX_pos >= 79) THEN
                state := 5;
            END_IF;
        5:                                      (* 边 2：(80,20)->(80,80) *)
            y_tgt := 80;
            IF (AxisY_pos <= 81) AND (AxisY_pos >= 79) THEN
                state := 6;
            END_IF;
        6:                                      (* 边 3：(80,80)->(20,80) *)
            x_tgt := 20;
            IF (AxisX_pos <= 21) AND (AxisX_pos >= 19) THEN
                state := 7;
            END_IF;
        7:                                      (* 边 4：(20,80)->(20,20) 闭合 *)
            y_tgt := 20;
            IF (AxisY_pos <= 21) AND (AxisY_pos >= 19) THEN
                state := 8;
            END_IF;
        8:                                      (* 抬笔 *)
            z_tgt := 10;
            IF AxisZ_pos >= 9 THEN
                state := 9;
            END_IF;
        9:                                      (* 回中心并完成 *)
            x_tgt := 50; y_tgt := 50;
            IF (AxisX_pos <= 51) AND (AxisX_pos >= 49) AND (AxisY_pos <= 51) AND (AxisY_pos >= 49) THEN
                state := 10;
                plot_done := TRUE;
            END_IF;
    ELSE
        state := 0;                              (* 意外状态：回待机 *)
    END_CASE;
END_IF;
